No files edited. I’ll add the route using the same `createSession(user.id)` flow as login, then add tests for immediate sign-in, validation, and duplicate emails. After implementation, I’ll run `npm test` and `npm run typecheck`.

In `src/api/account.ts`, replace the first two imports with:

```ts
import { createUser, getUser, publicUser, UserError } from "../auth/users.ts";
import { createSession, revokeSession } from "../auth/session.ts";
```

Add this entry to `accountRoutes`:

```ts
{
  method: "POST",
  path: "/api/signup",
  handler: (req) => {
    const email = field(req.body, "email");
    const name = field(req.body, "name");
    const password = field(req.body, "password");
    if (email === undefined || name === undefined || password === undefined) {
      return json(400, { error: "email, name and password are required" });
    }
    try {
      const user = createUser(email, name, password);
      const session = createSession(user.id);
      return json(201, { token: session.token, user: publicUser(user) });
    } catch (err) {
      if (err instanceof UserError) return json(400, { error: err.message });
      throw err;
    }
  },
},
```

Create `test/signup.test.ts` with:

```ts
import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { app } from "../src/api/routes.ts";
import { resetUsers } from "../src/auth/users.ts";
import { resetSessions } from "../src/auth/session.ts";

const signup = (body: unknown) =>
  app({ method: "POST", path: "/api/signup", body, headers: {} });

beforeEach(() => {
  resetUsers();
  resetSessions();
});

test("signup returns a public user and a working session", async () => {
  const res = await signup({
    email: " ADA@example.com ",
    name: " Ada ",
    password: "correct horse",
  });
  assert.equal(res.status, 201);
  const { token, user } = res.body as {
    token: string;
    user: { id: string; email: string; name: string };
  };
  assert.equal(typeof token, "string");
  assert.ok(token.length > 0);
  assert.equal(typeof user.id, "string");
  assert.deepEqual(user, {
    id: user.id,
    email: "ada@example.com",
    name: "Ada",
  });

  const me = await app({
    method: "GET",
    path: "/api/me",
    headers: { authorization: `Bearer ${token}` },
  });
  assert.equal(me.status, 200);
  assert.deepEqual(me.body, user);
});

test("signup rejects missing or non-string fields", async () => {
  const valid = {
    email: "ada@example.com",
    name: "Ada",
    password: "correct horse",
  };
  for (const field of ["email", "name", "password"]) {
    for (const value of [undefined, 123]) {
      const res = await signup({ ...valid, [field]: value });
      assert.equal(res.status, 400);
      assert.deepEqual(res.body, {
        error: "email, name and password are required",
      });
    }
  }
});

test("signup returns UserError messages as 400 responses", async () => {
  const cases = [
    { email: "invalid", password: "correct horse", error: "invalid email" },
    {
      email: "ada@example.com",
      password: "short",
      error: "password must be at least 8 characters",
    },
  ];
  for (const { email, password, error } of cases) {
    const res = await signup({ email, name: "Ada", password });
    assert.equal(res.status, 400);
    assert.deepEqual(res.body, { error });
  }
});

test("signup rejects duplicate emails case-insensitively", async () => {
  const body = {
    email: "ada@example.com",
    name: "Ada",
    password: "correct horse",
  };
  assert.equal((await signup(body)).status, 201);
  const res = await signup({ ...body, email: "ADA@example.com" });
  assert.equal(res.status, 400);
  assert.deepEqual(res.body, { error: "email already registered" });
});
```
